[
  {
    "statement": "Several interventions have shown effectiveness for restoring peatland vegetation in degraded peatlands.",
    "citations": []
  },
  {
    "statement": "Interventions for restoring peatland vegetation in degraded peatlands may be relevant to agricultural landscapes.",
    "citations": []
  },
  {
    "statement": "Multiple intervention techniques have demonstrated positive results for peatland restoration.",
    "citations": []
  },
  {
    "statement": "The moss layer transfer technique showed that restored areas developed communities of bog-characteristic plant species within 11 years.",
    "citations": []
  },
  {
    "statement": "Restored areas using the moss layer transfer technique had greater moss and bryophyte cover, including Sphagnum, compared to unrestored areas after 4 to 8 years.",
    "citations": []
  },
  {
    "statement": "Multiple intervention approaches, excluding moss layer transfer, were found to increase total moss cover, bryophyte cover, Sphagnum moss cover, herbaceous plant cover, and overall vegetation cover in bogs and other peatlands.",
    "citations": []
  },
  {
    "statement": "Surface covering with straw mulch showed mixed results for peatland restoration.",
    "citations": []
  },
  {
    "statement": "Covering the surface with straw mulch increased the number of fen-characteristic plants present but did not affect the cover of those plants.",
    "citations": []
  },
  {
    "statement": "The introduction of seeds from peatland trees and shrubs demonstrated variable outcomes.",
    "citations": []
  },
  {
    "statement": "Some studies on seed introduction showed greater shrub cover and total vegetation cover in sown plots compared to unsown plots.",
    "citations": []
  },
  {
    "statement": "Other studies on seed introduction found no difference in shrub cover or species richness between sown and unsown plots.",
    "citations": []
  },
  {
    "statement": "Survival rates for seedlings from introduced seeds were variable.",
    "citations": []
  },
  {
    "statement": "Some studies reported the death of introduced seedlings within short timeframes.",
    "citations": []
  }
]

