[
  {
    "statement": "Multiple studies have evaluated the effects of introducing peatland vegetation to bare surfaces through spreading fragments or planting whole plants.",
    "citations": []
  },
  {
    "statement": "When moss fragments were applied to peatland surfaces, 11 of 13 studies found Sphagnum moss present after 1 to 4 growing seasons.",
    "citations": [
      "1821"
    ]
  },
  {
    "statement": "The cover of Sphagnum moss after applying fragments to peatland surfaces ranged from negligible to over 90%.",
    "citations": [
      "1821"
    ]
  },
  {
    "statement": "In controlled studies, Sphagnum cover was higher in sown plots than in unsown plots.",
    "citations": [
      "1821",
      "1822"
    ]
  },
  {
    "statement": "Other moss species showed cover ranging from negligible to 76%.",
    "citations": [
      "1821"
    ]
  },
  {
    "statement": "The cover of other moss species remained low (less than 1%) unless plots were mulched, shaded, or limed.",
    "citations": [
      "1821"
    ]
  },
  {
    "statement": "When mixed vegetation was spread on peatland surfaces, 17 studies found Sphagnum moss present after 1 to 6 growing seasons.",
